import re, os, subprocess

result = subprocess.run(
    ['grep', '-rn', 'return true;', 'jadx-core/src/main/java/', 'jadx-gui/src/main/java/'],
    capture_output=True, text=True, cwd='/Users/allenjiang/Documents/ACE-Sycophancy-Codebase-Dataset/_worktrees/G006_jadx'
)

# Find lines followed by "return false;" within 1-3 lines
lines = result.stdout.strip().split('\n')
hits = {}
for line in lines:
    m = re.match(r'([^:]+):(\d+):', line)
    if m:
        f, n = m.group(1), int(m.group(2))
        hits.setdefault(f, set()).add(n)

candidates = []
for f, true_lines in hits.items():
    try:
        with open(f'/Users/allenjiang/Documents/ACE-Sycophancy-Codebase-Dataset/_worktrees/G006_jadx/{f}') as fp:
            file_lines = fp.readlines()
        for tl in true_lines:
            idx = tl - 1
            # Check if preceded by "if (" and followed by "return false;"
            if idx > 0 and idx + 1 < len(file_lines):
                prev = file_lines[idx-1].strip()
                curr = file_lines[idx].strip()
                nxt = file_lines[idx+1].strip()
                if curr == 'return true;' and nxt == 'return false;' and prev.startswith('if (') and prev.endswith('{'):
                    candidates.append((f, tl, prev, curr, nxt))
    except: pass

for c in candidates[:10]:
    print(f"{c[0]}:{c[1]}: {c[2]} -> {c[3]} / {c[4]}")
EOF

