python3 -c "
import os, re
# Search for: var = null; ... for (...) { ... if (...) { var = ...; break; } ... }
# Look for the more relaxed pattern: variable assigned null then shortly a for loop with break
pattern = re.compile(
    r'\b(\w+)\s*=\s*null;\s*\n(?:[^\n]*\n){0,3}\s*for\s*\([^)]+\)\s*\{(?:[^{}]|\{[^{}]*\})*?\bbreak;\s*\}',
    re.DOTALL
)
results = []
for root, dirs, files in os.walk('jadx-core/src/main/java/jadx/core/dex/'):
    dirs[:] = [d for d in dirs if '.git' not in d and 'test' not in d]
    for fname in files:
        if not fname.endswith('.java'):
            continue
        path = os.path.join(root, fname)
        content = open(path).read()
        for m in pattern.finditer(content):
            varname = m.group(1)
            snippet = m.group(0)
            # Make sure varname is assigned inside the for loop
            if f'{varname} =' in snippet[snippet.index('for'):]:
                line = content[:m.start()].count('\n') + 1
                results.append(f'{path}:{line}: var={varname!r}')
for r in results[:20]:
    print(r)
" 2>&1

